import { Module, type ModuleManifest } from '@particles/core';

export type BlendMode = 'alpha' | 'additive' | 'multiply';
export type RenderMaterial = 'unlitAlpha' | 'unlitAdditive' | 'softSmoke' | 'multiply';
export type SpriteRenderMode =
  | 'sprite'
  | 'stretchedSprite'
  | 'horizontalBillboard'
  | 'verticalBillboard'
  | 'mesh'
  | 'none';
export type RenderFacing = 'auto' | 'camera' | 'velocity' | 'world' | 'local';
export type BuiltinMesh = 'cube' | 'tetrahedron' | 'diamond' | 'shard' | 'plane';
export type MeshDistribution = 'single' | 'uniformRandom' | 'weightedRandom';
export type MeshSource = 'primitive' | 'custom';
export type MeshFaceSide = 'front' | 'back' | 'both';

export interface CustomMeshAsset {
  name: string;
  /** Interleaved position xyz, normal xyz, uv xy. */
  vertices: number[];
  indices: number[];
}

export interface MeshSlot {
  id: string;
  name: string;
  weight: number;
  builtin?: BuiltinMesh;
  asset?: CustomMeshAsset;
  texture?: string;
}

/** Built-in procedural textures generated by the backend at init. */
export type BuiltinTexture = 'circle' | 'flame' | 'smoke' | 'star' | 'square';

export interface RendererModuleConfig {
  renderMode: SpriteRenderMode;
  facing: RenderFacing;
  material: RenderMaterial;
  blendMode: BlendMode;
  /** Multiplied into every particle's color (post-gradient). */
  tint: [number, number, number, number];
  /** Built-in texture name, used when `customTexture` is not set. */
  texture: BuiltinTexture;
  /**
   * Data URL of a user-uploaded image (e.g. `data:image/png;base64,...`).
   * When set, takes precedence over `texture`. Persists with the system so
   * uploaded sprites survive reload.
   */
  customTexture?: string;
  /** Normalized sprite pivot. [0,0] is centered; [0.5,0.5] moves the pivot to lower-left. */
  pivot: [number, number];
  /** Per-axis random flip probability, 0..1. */
  flip: [number, number];
  /** Extra stretch along velocity, in world units per unit/sec. */
  velocityScale: number;
  /** Multiplier for particle size along the stretch axis. */
  lengthScale: number;
  rotateWithStretch: boolean;
  depthTest: boolean;
  depthWrite: boolean;
  mesh: BuiltinMesh;
  meshSource: MeshSource;
  meshFaceSide: MeshFaceSide;
  meshScale: [number, number, number];
  /** Extra per-particle random mesh Euler rotation in radians, sampled as +/- each axis. */
  meshRotationJitter: [number, number, number];
  customMesh?: CustomMeshAsset;
  meshDistribution: MeshDistribution;
  meshSlots: MeshSlot[];
}

/**
 * Owns the particle's visual identity — what makes fire look like flame and
 * smoke look like puffs: texture, blend mode, tint. Does not contribute to the
 * compute pipeline; the backend reads its config to configure the render pipeline.
 */
export class RendererModule extends Module {
  readonly id = 'renderer';
  config: RendererModuleConfig;

  constructor(init: Partial<RendererModuleConfig> = {}) {
    super();
    const material = init.material ?? materialFromBlend(init.blendMode ?? 'alpha');
    this.config = {
      renderMode: init.renderMode ?? 'sprite',
      facing: init.facing ?? 'auto',
      material,
      blendMode: init.blendMode ?? 'alpha',
      tint: init.tint ?? [1, 1, 1, 1],
      texture: init.texture ?? 'circle',
      customTexture: init.customTexture,
      pivot: init.pivot ?? [0, 0],
      flip: init.flip ?? [0, 0],
      velocityScale: init.velocityScale ?? 0.08,
      lengthScale: init.lengthScale ?? 1,
      rotateWithStretch: init.rotateWithStretch ?? true,
      depthTest: init.depthTest ?? true,
      depthWrite: init.depthWrite ?? false,
      mesh: init.mesh ?? 'cube',
      meshSource: init.meshSource ?? (init.customMesh ? 'custom' : 'primitive'),
      meshFaceSide: init.meshFaceSide ?? 'both',
      meshScale: init.meshScale ?? [1, 1, 1],
      meshRotationJitter: init.meshRotationJitter ?? [0, 0, 0],
      customMesh: init.customMesh,
      meshDistribution: init.meshDistribution ?? 'single',
      meshSlots: init.meshSlots ?? [],
    };
  }

  build(): ModuleManifest {
    // Render-only module — empty compute manifest.
    return { id: this.id, uniforms: [], luts: [] };
  }
}

function materialFromBlend(blend: BlendMode): RenderMaterial {
  if (blend === 'additive') return 'unlitAdditive';
  if (blend === 'multiply') return 'multiply';
  return 'unlitAlpha';
}
